//! SeedSigner's published SeedQR test vectors, run against the ingress validator.
//!
//! Source: the SeedQR format specification's "Test SeedQRs - Sample test vectors to verify
//! your own encode and decode implementations" section,
//! <https://github.com/SeedSigner/seedsigner/blob/dev/docs/seed_qr/README.md>. All nine
//! are here, in both formats, unmodified. Nothing in this file was generated by this
//! project; where a value had to be re-expressed (the specification prints the
//! CompactSeedQR payload as a bit string and again as a Python bytes literal, and this
//! file uses hex) the re-expression is proven rather than trusted - see
//! `the_published_fields_of_each_vector_agree`, which recomputes the entropy from the
//! published digit stream with the specification's own rule and compares it to the
//! published payload. A transcription slip in either column fails that test.
//!
//! Vectors 2 and 6 carry an embedded `0x00`, 7 a `0x0a`, 8 a `0x0d`, 9 a `0x0d 0x0a`, and
//! vector 1 ENDS in `0x0a` - the specification chose them for exactly that reason ("Take
//! extra care to confirm that your implementation correctly reads these characters and
//! all remaining data after it!"). They are the reason this crate's decoder takes `&[u8]`
//! and trims nothing.

use notyas_core::bip39::{self, Checksum};
use notyas_core::seedqr::{self, Format, IngressError};

/// One published vector, in the three forms the specification prints it in.
struct Vector {
    /// The vector's number in the specification, so a failure names the row upstream.
    number: u32,
    mnemonic: &'static str,
    /// "Standard SeedQR digit stream" verbatim.
    digits: &'static str,
    /// "CompactSeedQR bytestream" as hex. The specification gives this as a Python bytes
    /// literal and as a bit string; both are the same value, and this file's transcription
    /// is checked against the digit stream column below.
    entropy_hex: &'static str,
}

